{"format":2,"nsh":"0.7.1","sets":[{"assets":[],"declarations":"/** The phone's controller: sign-in, the account's devices, connections. Port-level calls reject with `<code>: <sentence>` (`invalid_email`, `invalid_code`, `rate_limited`, `signed_out`, `unreachable`, `unsupported`, `unavailable`, `network`). */
export interface ControllerModule {
  /** The account this phone is signed in to (JSON `{ accountId, identity, deviceId }`, `identity` the shared projection `{ provider, accountId, displayName, initial }`), or `null`. */
  restore(): Promise<string>;
  /** Emails a sign-in code to `email` in `locale`'s language. Resolves with the challenge (JSON `{ challengeId, email, codeLength, retryAfterSeconds, expiresAt }`). */
  requestCode(email: string, locale?: string | null): Promise<string>;
  /** Checks the emailed code of `challengeId`, registers this phone with the account and joins the account's device network. Resolves with the account (JSON, as `restore()`). */
  verifyCode(challengeId: string, code: string): Promise<string>;
  /** Signs out: closes every device connection, leaves the device network and forgets the account on this phone. */
  signOut(): Promise<void>;
  /** The account's devices this phone may drive (JSON array of `{ deviceId, name, kind, os, model, clientVersion, online, lastSeenAt, connectable, unavailable, route, relayVia, relayViaName, latencyMs }`). */
  listDevices(): Promise<string>;
  /** This phone's device network (JSON `{ state, reason, role, virtualIp, natType, relayNodes, updatedAtMs, keyStore }`). */
  network(): Promise<string>;
  /** Opens an authenticated OBP connection to the device `deviceId` over the device network; resolves with the connection's handle once the device answered `hello`. `optionsJson` (JSON `{ fleet: { protocol, cursor } }`) makes the hello a fleet hello with that vector cursor; a redial resumes from the cursor of what was delivered since. */
  connect(deviceId: string, optionsJson?: string | null): Promise<number>;
  /** The account's runtime hosts this phone may enter the fleet through, best first (JSON `{ entryCandidates: [deviceId], candidates: [{ deviceId, online, fleetProtocol, fullHost, latencyMs, fleetLoad, version }] }`): online, then `fleet_v1`, then a desktop, then lowest latency, then fewest attached clients, then newest version. */
  entryCandidates(): Promise<string>;
  /** The device backend of a connection: JSON `{ version, platform, dataDir, scope, capabilities, deviceId }`. */
  hello(connection: number): Promise<string>;
  /** Runs one command on the device backend. `argsJson` is the args object the UI's `invoke(command, args)` received; resolves with the JSON of the result, rejects with the backend's own error text. */
  invoke(connection: number, command: string, argsJson: string): Promise<string>;
  /** Long poll for the device backend's events: a JSON array of `{ seq, event, payload }` after `afterSeq` (or after the last batch). Rejects when the connection dropped; the next call redials and resumes. */
  nextEvents(connection: number, afterSeq?: number | null): Promise<string>;
  /** Closes a device connection for good. */
  disconnect(connection: number): Promise<void>;
}

/** The phone's controller: sign-in, the account's devices, connections. Port-level calls reject with `<code>: <sentence>` (`invalid_email`, `invalid_code`, `rate_limited`, `signed_out`, `unreachable`, `unsupported`, `unavailable`, `network`). */
export declare const Controller: ControllerModule;

